<!--vbase-->
<template>
  <q-banner
    inline-actions
    :class="messageCategoryClass"
    class="msg-banner text-white"
  >
    <div class="message">
      {{ message }}
    </div>
    <template v-slot:avatar>
      <q-btn v-if="!back_route" class="text-weight-bold" to="/dashboard">
        {{ $t('dashboard') }}
      </q-btn>
      <q-btn v-if="back_route" class="text-weight-bold" @click="backRoute">
        {{ $t('back') }}
      </q-btn>
    </template>
    <template v-slot:action>
      <q-btn v-if="dissmiss_btn" :label="$t('dismiss')" @click="dismiss()" />
    </template>
  </q-banner>
</template>

<script lang="ts">
import { $ } from 'src/pages/assets';
import { defineComponent } from 'vue';

export default defineComponent({
  el: '#app',
  props: {
    message: {
      type: String,
      default: '',
    },
    messageCategoryClass: {
      type: String,
      default: 'error-banner',
    },
    back_route: {
      type: Boolean,
      default: false,
    },
    back_event: {
      type: Boolean,
      default: false,
    },
    dissmiss_btn: {
      type: Boolean,
      default: true,
    },
  },

  components: {},
  data() {
    return {};
  },
  // mounted: function () {

  // },
  methods: {
    dismiss() {
      ($('.msg-banner') as HTMLElement).remove();
      const event = new CustomEvent('dismiss_message', {});
      document.dispatchEvent(event);
    },

    backRoute() {
      try {
        if (history.state.back) {
          this.$router.back();
          return;
        }
        this.$router.push('/dashboard');
      } catch (err) {
        logError(err);
        this.$router.push('/dashboard');
      }
    },
  },
  setup() {
    return {};
  },
});
</script>

<style lang="scss" scoped>
.msg-banner {
  color: white;
  position: absolute;
  width: calc(100% - 58px);
  z-index: 2;
}

.message {
  margin: auto;
  width: 100%;
  text-align: center;
  font-size: 20px;
  font-weight: bold;
}
</style>
